import { MeshStandardNodeMaterial } from 'three/webgpu';
import { color, texture, uv, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, PointLight } = ctx.THREE;

  const mainGroup = new Group();

  // 1. PALETTE FROM SPEC
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Convert colors to Three.js-friendly formats
  const cInk = new ctx.THREE.Color(colors.ink);
  const cPaper = new ctx.THREE.Color(colors.paper);
  const cAccent = new ctx.THREE.Color(colors.accent);
  const cSurface = new ctx.THREE.Color(colors.surface);

  // 2. STAGE BACKDROP (Build backdrop plane at z = -2.5, matching 7x6 dimensions)
  const backdropGeo = new PlaneGeometry(7.0, 6.0);
  const backdropMat = new MeshStandardNodeMaterial({
    roughness: 0.8,
    metalness: 0.1,
    depthWrite: false
  });

  // Vertical gradient Node logic for Backdrop: surface -> ink -> surface
  const vUv = uv();
  const gradNode = mix(
    color(cSurface),
    mix(color(cInk), color(cSurface), smoothstep(0.4, 0.9, vUv.y)),
    smoothstep(0.1, 0.6, vUv.y)
  );
  backdropMat.colorNode = gradNode;

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -2.5);
  mainGroup.add(backdropMesh);

  // 3. CONTACT SHADOW (For grounded product feel)
  const shadowGeo = new PlaneGeometry(2.4, 0.4);
  const shadowMat = new MeshStandardNodeMaterial({
    roughness: 1.0,
    metalness: 0.0,
    transparent: true,
    opacity: 0.5,
    depthWrite: false
  });
  const shadowUv = uv();
  const distFromCenter = shadowUv.sub(0.5).length();
  shadowMat.colorNode = color(0x000000);
  shadowMat.opacityNode = smoothstep(0.5, 0.1, distFromCenter).mul(0.55);

  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -1.35, 0.1);
  mainGroup.add(shadowMesh);

  // 4. MAIN SUBJECT: Textured card plane (Engineered Gradient Surface, high-end machined feel)
  const cardGeo = new PlaneGeometry(2.2, 2.7);
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.4,
    transparent: true
  });

  // Complex multi-layered engineered gradient for card surface: ink to dark grey edge with thin accent line
  const borderUv = uv();
  const borderX = smoothstep(0.01, 0.03, borderUv.x).mul(smoothstep(0.99, 0.97, borderUv.x));
  const borderY = smoothstep(0.01, 0.03, borderUv.y).mul(smoothstep(0.99, 0.97, borderUv.y));
  const borderMask = borderX.mul(borderY);

  const centralGrad = mix(color(cInk), color(0x202028), borderUv.y);
  const finalCardColor = mix(color(cAccent), centralGrad, borderMask);
  cardMat.colorNode = finalCardColor;

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0);
  mainGroup.add(cardMesh);

  // 5. ASSET LOAD: Orb Decor
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/orb-decor.png';
  ctx.textureLoader.loadTexture(imageUrl).then((textureMap) => {
    // Inject loaded texture inside bounds with high roughness to represent machined brushed details
    const overlayGeo = new PlaneGeometry(1.8, 1.8);
    const overlayMat = new MeshStandardNodeMaterial({
      map: textureMap,
      transparent: true,
      roughness: 0.7,
      metalness: 0.5,
      depthWrite: false
    });
    const overlayMesh = new Mesh(overlayGeo, overlayMat);
    overlayMesh.position.set(0, 0.1, 0.05);
    mainGroup.add(overlayMesh);
  }).catch((err) => {
    console.warn("Failed to load orb-decor.png texture", err);
  });

  // 6. DETAILED LOCAL LIGHTING (Product-shot setup)
  const localRimLight = new PointLight(cAccent, 1.3, 8);
  localRimLight.position.set(2, 3, 1);
  mainGroup.add(localRimLight);

  const localKeyLight = new PointLight(cPaper, 0.9, 10);
  localKeyLight.position.set(-2, -1, 3);
  mainGroup.add(localKeyLight);

  // 7. ENTRANCE ANIMATION (GSAP - rise-in and weighted settle)
  gsap.fromTo(mainGroup.position, 
    { y: -0.7 }, 
    { y: -0.3, duration: 1.1, ease: 'power4.out', delay: 0.1 }
  );
  gsap.fromTo(mainGroup.rotation,
    { x: 0.12, y: -0.05 },
    { x: 0, y: 0, duration: 1.4, ease: 'power3.out' }
  );

  // 8. CLEANUP CONTRACT
  mainGroup.userData.cleanup = function() {
    backdropGeo.dispose();
    backdropMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();
    gsap.killTweensOf(mainGroup.position);
    gsap.killTweensOf(mainGroup.rotation);
  };

  return mainGroup;
}
